OUT = Path(__file__).resolve().parents[1]; EV = OUT / "evidence"
def table(text, cols):
    rows = [[c.strip() for c in ln.split("|")] for ln in text.strip().split("\n") if ln.strip()]
    bad = [r for r in rows if len(r) != len(cols)]
    assert not bad, (len(cols), [(len(r), r[0]) for r in bad])
    return pd.DataFrame(rows, columns=cols)

