# ---- price basis comparison
c = pd.read_csv(EV / "nse_vs_yahoo_all_universe_rows.csv")
def explain(r):
    s, d = r.symbol, r.date
    if s == "BHARTIARTL": return ("0.91818 (2019 rights) x 0.98157 (2021 rights)", 0.91818*0.98157) if d < "2019-04-23" else (("0.98157 (2021 rights)", 0.98157) if d < "2021-09-27" else ("none - no later action", 1.0))
    if s == "HDFCBANK": return ("0.5 (2019 FV split) x 0.5 (2025 bonus)", 0.25) if d < "2019-09-19" else (("0.5 (2025 bonus)", 0.5) if d < "2025-08-26" else ("none - no later action", 1.0))
    if s == "ITC": return ("0.96292 (2025 ITC Hotels demerger)", 0.96292) if d < "2025-01-06" else ("none - no later action", 1.0)
    if s == "RELIANCE": return ("0.99062 (2020 rights) x 0.92300 (2023 demerger) x 0.5 (2024 bonus)", 0.99062*0.923*0.5) if d < "2020-05-13" else (("0.92300 (2023 demerger) x 0.5 (2024 bonus)", 0.4615) if d < "2023-07-20" else (("0.5 (2024 bonus)", 0.5) if d < "2024-10-28" else ("none - no later action", 1.0)))
    if s == "HINDUNILVR": return ("none applied - although the 2025-12-05 demerger is later than this date", 1.0)
    return ("none - no later price-adjusting action", 1.0)
ex = c.apply(explain, axis=1, result_type="expand"); c["later_actions_explaining_ratio"] = ex[0]; c["expected_ratio_from_factors"] = ex[1].round(5)
c["residual_ratio_minus_expected"] = (c.ratio_yahoo_close_to_nse_close - c.expected_ratio_from_factors).round(5)
c["ohlc_scaled_by_same_factor"] = (c[["ratio_yahoo_open_to_nse_open","ratio_yahoo_high_to_nse_high","ratio_yahoo_low_to_nse_low"]].sub(c.ratio_yahoo_close_to_nse_close, axis=0).abs().max(axis=1) < 2e-5)
c["volume_scaled_by_inverse_factor"] = ((c.ratio_yahoo_volume_to_nse_volume * c.ratio_yahoo_close_to_nse_close - 1).abs() < 2e-3)
c["status"] = np.where(c.residual_ratio_minus_expected.abs() < 2e-5, "EXPLAINED", "UNEXPLAINED")
c.loc[(c.symbol == "HINDUNILVR"), "status"] = "EXPLAINED as unadjusted (vendor did not back-adjust the later demerger)"
c["data_class"] = "NSE columns = official exchange file (verified); yahoo columns = vendor; factors = observed ratios, not exchange-published"
c = c.round(6); c.to_csv(OUT / "price_basis_comparison.csv", index=False)
print("price basis rows", len(c), c.status.value_counts().to_dict(), "| OHLC same factor:", int(c.ohlc_scaled_by_same_factor.sum()), "| volume inverse:", int(c.volume_scaled_by_inverse_factor.sum()), "| max |residual|:", c.residual_ratio_minus_expected.abs().max())
print(c[~c.volume_scaled_by_inverse_factor][["date","symbol","ratio_yahoo_volume_to_nse_volume","ratio_yahoo_close_to_nse_close"]].to_string())

